CREATE TABLE "reference_change" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "reference_change_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"name" text NOT NULL,
	"entry" text,
	"change" text NOT NULL,
	"before" jsonb,
	"after" jsonb,
	"staff_id" text,
	"staff_label" text,
	"at" timestamp with time zone NOT NULL,
	CONSTRAINT "reference_change_name" CHECK (name in ('bpbdContacts', 'education', 'responseActions', 'forecast', 'volcanoes', 'facilityNumbers')),
	CONSTRAINT "reference_change_change" CHECK (change in ('added', 'changed', 'removed', 'imported')),
	CONSTRAINT "reference_change_staff" CHECK (("reference_change"."staff_id" is null) = ("reference_change"."staff_label" is null))
);
