CREATE INDEX "reference_change_by_name" ON "reference_change" USING btree ("name","id");--> statement-breakpoint
CREATE TRIGGER "reference_change_append_only" BEFORE UPDATE OR DELETE ON "reference_change" FOR EACH ROW EXECUTE FUNCTION append_only();
